    add("T082", title="context 一：取消与传播", level="advanced", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="worker reached checkpoint, requesting cancel\nworker stopped: context canceled\nmain observed worker exit\nchild canceled by parent: context canceled", run="go run main.go",
        concepts=["context", "取消", "传播", "Done"],
        summary="用 context.WithCancel 取消下游任务，并演示子 context 随父取消。",
        objective="能用 context 取消 goroutine，并用 Done() channel 检测取消、说明取消会向下传播。",
        prereq=["T074 channel 三：close 与 range 接收"],
        pitfalls=["把 context 存进结构体长期持有：应作为函数第一个参数按调用链传递。", "忘记调用 cancel()：会泄漏资源（定时器/子节点），应用 defer cancel()。"],
        exercises=[{"prompt": "实现一个带 ctx 的循环任务，在 ctx.Done 时打印退出原因并关闭 done。", "hint": "select { case <-ctx.Done(): ...; default: ... }", "answer": "循环内 select 监听 ctx.Done()，收到后 close(done) 并 return。"}],
        explain="context 用于在调用链上传递取消信号、截止时间与请求范围值。WithCancel 返回派生 ctx 与 cancel；调用 cancel 会关闭 ctx.Done() 返回的 channel，所有监听它的下游任务据此提前退出。示例启动一个循环任务，任务在某个检查点自行 cancel，主流程通过 done channel 等待其确认退出——用 channel 同步而非睡眠，因此输出确定。随后演示子 context 随父取消：父 cancel 后子的 Done 也关闭。约定：context 作为函数第一个参数向下传递，不在结构体里长期保存，并总是 defer cancel()。")
